let currentLanguage = "es";
const languageButton = document.querySelector("#language-toggle");
function setLanguage(language) {
  currentLanguage = translations[language] ? language : "es";
  try { localStorage.setItem("portfolio-language", currentLanguage); } catch (error) { /* La web sigue funcionando si el almacenamiento está bloqueado. */ }
  document.documentElement.lang = currentLanguage;
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    const translation = translations[currentLanguage][key];
    if (translation) element.innerHTML = translation;
  });
  // También traduce los textos alternativos de imágenes, aunque no tengan data-i18n.
  document.querySelectorAll("[data-i18n-alt]").forEach((element) => {
    const altKey = element.dataset.i18nAlt;
    const translation = translations[currentLanguage][altKey];
    if (translation) element.setAttribute("alt", translation);
  });
  if (languageButton) {
    languageButton.textContent = currentLanguage === "es" ? "ES / EN" : "EN / ES";
    languageButton.setAttribute("aria-label", currentLanguage === "es" ? "Change language to English" : "Cambiar idioma a español");
  }
}
if (languageButton) {
  languageButton.addEventListener("click", () => {
    const activeLanguage = document.documentElement.lang === "en" ? "en" : "es";
    setLanguage(activeLanguage === "es" ? "en" : "es");
  });
}
// Idioma inicial del portfolio: español. El usuario puede cambiarlo con el selector. 
setLanguage("es");
const yearElement = document.querySelector("#year");
if (yearElement) yearElement.textContent = String(new Date().getFullYear());


// Acordeones exclusivos: al abrir uno, se cierra cualquier otro
// que no sea un contenedor ancestro necesario para mostrarlo.
document.addEventListener("toggle", (event) => {
  const opened = event.target;
  if (!(opened instanceof HTMLDetailsElement) || !opened.open) return;

  // Conserva únicamente el desplegable seleccionado y sus contenedores padre.
  const requiredAncestors = new Set();
  let ancestor = opened.parentElement;
  while (ancestor) {
    if (ancestor instanceof HTMLDetailsElement) requiredAncestors.add(ancestor);
    ancestor = ancestor.parentElement;
  }

  document.querySelectorAll("details[open]").forEach((item) => {
    if (item !== opened && !requiredAncestors.has(item)) item.open = false;
  });

  // En escritorio y móvil, coloca el desplegable recién abierto al inicio
  // del área visible, sin que la cabecera fija tape su título.
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      if (!opened.isConnected || !opened.open) return;
      const header = document.querySelector(".site-header");
      const headerHeight = header ? header.getBoundingClientRect().height : 0;
      const top = window.scrollY + opened.getBoundingClientRect().top - headerHeight - 12;
      window.scrollTo({ top: Math.max(0, top), behavior: "smooth" });
    });
  });
}, true);
